const photos=[['27','Circles among the green'],['08','A new point of view'],['13','Through the orange door'],['22','A secret beneath the canopy'],['03','Take the little path'],['19','A world of your own'],['35','Hidden in plain sight'],['04','When the garden glows']];let current=0;const gallery=document.querySelector('#gallery');function show(i){current=(i+photos.length)%photos.length;const[id,caption]=photos[current];const image=document.querySelector('#gallery-photo');image.src=`assets/${id}.webp`;image.alt=caption;document.querySelector('#gallery-caption').textContent=`${String(current+1).padStart(2,'0')} / ${String(photos.length).padStart(2,'0')} — ${caption}`;}document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>{show(photos.findIndex(p=>p[0]===b.dataset.photo));gallery.showModal();}));document.querySelector('#open-journal').addEventListener('click',()=>{show(0);gallery.showModal();});document.querySelector('#next').addEventListener('click',()=>show(current+1));document.querySelector('#previous').addEventListener('click',()=>show(current-1));gallery.addEventListener('keydown',e=>{if(e.key==='ArrowRight')show(current+1);if(e.key==='ArrowLeft')show(current-1);});document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});const toggle=document.querySelector('#night-toggle');toggle.addEventListener('click',()=>{const isDay=document.querySelector('#night').classList.toggle('day');toggle.setAttribute('aria-pressed',String(!isDay));document.querySelector('.night-copy h2').innerHTML=isDay?'A little green.<br>A little wonder.<br><em>All yours.</em>':'The garden<br>has a<br><em>midnight side.</em>';document.querySelector('.night-copy>p:not(.eyebrow)').innerHTML=isDay?'Let the daylight lead you.<br>There’s more around the next corner.':'Follow the glow. The garden has<br>another story after dark.';document.querySelector('#night-label').textContent=isDay?'THE GARDEN BY DAY':'THE GARDEN AT NIGHT';toggle.querySelector('b').textContent=isDay?'SWITCH TO NIGHT ↗':'SWITCH TO DAY ↗';toggle.querySelector('.switch-orb').textContent=isDay?'☀':'☾';document.querySelector('#time-note').textContent=isDay?'DAYLIGHT / FOLLOW THE GREEN':'AFTER HOURS / SAME GARDEN, ANOTHER WORLD';});const menu=document.querySelector('.menu-toggle');menu.addEventListener('click',()=>{const open=document.querySelector('header').classList.toggle('menu-open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('header').classList.remove('menu-open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');}));const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduced){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.08});document.querySelectorAll('.secret-copy,.circles-heading,.journal-heading,.invitation h2').forEach(e=>{e.classList.add('reveal');observer.observe(e);});const flies=document.querySelector('.fireflies');for(let i=0;i<16;i++){const f=document.createElement('i');f.style.left=`${8+(i*67)%85}%`;f.style.top=`${20+(i*31)%65}%`;f.style.animationDelay=`${i*.73}s`;f.style.animationDuration=`${4+i%5}s`;flies.append(f);}const stage=document.querySelector('.portal-stage');document.querySelector('.entrance').addEventListener('pointermove',e=>{if(window.innerWidth>900){const x=(e.clientX/window.innerWidth-.5)*12;const y=(e.clientY/window.innerHeight-.5)*8;stage.style.marginLeft=`${x}px`;stage.style.marginTop=`${y}px`;}});}

const dreamDoor=document.querySelector('#dream-door');dreamDoor.addEventListener('click',()=>{const moonlit=document.querySelector('.entrance').classList.toggle('moonlit');dreamDoor.setAttribute('aria-pressed',String(moonlit));dreamDoor.setAttribute('aria-label',moonlit?'Return the doorway to the daylight garden':'Open the doorway to the moonlit garden');dreamDoor.querySelector('img').src=moonlit?'assets/04.webp':'assets/13.webp';dreamDoor.querySelector('img').alt=moonlit?'The real garden illuminated by string lights after dark':'An open circular room tucked into tropical plants';document.querySelector('#door-label').textContent=moonlit?'BRING BACK THE DAYLIGHT':'TURN THE GARDEN TO NIGHT';document.querySelector('#door-note').innerHTML=moonlit?'The familiar fades.<br><em>The garden begins to glow.</em>':'Some doors lead to rooms.<br><em>This one leads somewhere else.</em>';});

const lanternScene=document.querySelector('#lantern-scene'),lanternRange=document.querySelector('#lantern-position');let lanternX=50,lanternY=55;const foundWonders=new Set();const wonders={room:{x:53,y:46,title:'A door into<br><em>the unexpected.</em>',copy:'A round entrance. A curved wooden interior. Your own little circle, tucked into the garden.',photo:'13',alt:'A circular room with orange doors and a curved wooden interior',number:'01 / THE CIRCULAR ROOMS'},path:{x:31,y:75,title:'The little path<br><em>less ordinary.</em>',copy:'Walkways wind between the rooms and the green. Take your time. There is another perspective around the corner.',photo:'03',alt:'A raised walkway beside lush tropical foliage',number:'02 / FOLLOW THE GREEN'},night:{x:79,y:29,title:'A secret that<br><em>stays up late.</em>',copy:'String lights trace the garden after dark. The paths and circular rooms take on a different glow.',photo:'04',alt:'The garden path and circular rooms illuminated at night',number:'03 / AFTER THE SUN'}};function moveLantern(x,y){lanternX=Math.max(0,Math.min(100,x));lanternY=Math.max(0,Math.min(100,y));lanternScene.style.setProperty('--light-x',lanternX+'%');lanternScene.style.setProperty('--light-y',lanternY+'%');lanternRange.value=Math.round(lanternX);}function pointLantern(e){const r=lanternScene.getBoundingClientRect();moveLantern((e.clientX-r.left)/r.width*100,(e.clientY-r.top)/r.height*100);}lanternScene.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'||e.buttons===1)pointLantern(e);});lanternScene.addEventListener('pointerdown',pointLantern);lanternScene.addEventListener('keydown',e=>{if(e.target!==lanternScene)return;const directions={ArrowLeft:[-5,0],ArrowRight:[5,0],ArrowUp:[0,-5],ArrowDown:[0,5]};if(directions[e.key]){e.preventDefault();const[x,y]=directions[e.key];moveLantern(lanternX+x,lanternY+y);}});lanternRange.addEventListener('input',()=>moveLantern(Number(lanternRange.value),lanternY));function revealWonder(key){const w=wonders[key];moveLantern(w.x,w.y);foundWonders.add(key);document.querySelectorAll('[data-wonder]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.wonder===key));b.classList.toggle('found',foundWonders.has(b.dataset.wonder));});document.querySelector('#wonder-number').textContent=w.number;document.querySelector('#wonder-title').innerHTML=w.title;document.querySelector('#wonder-copy').textContent=w.copy;const photo=document.querySelector('#wonder-photo');photo.src='assets/'+w.photo+'.webp';photo.alt=w.alt;document.querySelector('#wonder-open').dataset.photo=w.photo;document.querySelector('#wonder-progress').textContent=foundWonders.size===3?'3 / 3 — YOU FOUND YOUR WAY INTO THE GARDEN.':foundWonders.size+' / 3 LITTLE WONDERS FOUND';lanternScene.classList.toggle('constellation-complete',foundWonders.size===3);}document.querySelectorAll('[data-wonder]').forEach(b=>b.addEventListener('click',()=>revealWonder(b.dataset.wonder)));document.querySelector('#light-garden').addEventListener('click',e=>{const lit=lanternScene.classList.toggle('fully-lit');e.currentTarget.setAttribute('aria-pressed',String(lit));e.currentTarget.textContent=lit?'Bring back the mystery ↗':'Light the whole garden ↗';});document.querySelector('#reset-wonders').addEventListener('click',()=>{foundWonders.clear();document.querySelectorAll('[data-wonder]').forEach(b=>{b.classList.remove('found');b.setAttribute('aria-pressed','false');});lanternScene.classList.remove('constellation-complete','fully-lit');document.querySelector('#light-garden').setAttribute('aria-pressed','false');document.querySelector('#light-garden').textContent='Light the whole garden ↗';document.querySelector('#wonder-progress').textContent='0 / 3 LITTLE WONDERS FOUND';document.querySelector('#wonder-number').textContent='A SMALL INVITATION';document.querySelector('#wonder-title').innerHTML='Let something<br><em>find you.</em>';document.querySelector('#wonder-copy').textContent='Three little lights. Three ways into the garden. Choose a firefly to open a window into the real Arenal Secret Garden.';document.querySelector('#wonder-photo').src='assets/13.webp';document.querySelector('#wonder-photo').alt='An open circular room entrance in the garden';document.querySelector('#wonder-open').dataset.photo='13';moveLantern(50,55);});
